package main

import (
	"fmt"
	"runtime"
	"sync"
	"unsafe"
)

type Todo struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

type store struct {
	mu    sync.Mutex
	todos []Todo
}

func (s *store) page(offset, limit int) []Todo {
	s.mu.Lock()
	defer s.mu.Unlock()
	all := make([]Todo, len(s.todos))
	copy(all, s.todos)
	end := min(offset+limit, len(all))
	return all[offset:end]
}

func main() {
	s := &store{}
	for i := 1; i <= 10000; i++ {
		s.todos = append(s.todos, Todo{ID: i, Title: "todo"})
	}
	const calls = 1000
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	n := 0
	for range calls {
		n = len(s.page(0, 50))
	}
	runtime.ReadMemStats(&after)
	fmt.Println("sizeof Todo:", unsafe.Sizeof(Todo{}), "bytes")
	fmt.Println("returned:", n, "todos")
	fmt.Println("allocated per call:", (after.TotalAlloc-before.TotalAlloc)/calls/1024, "KB")
}

package main

import (
	"encoding/json"
	"io"
	"sync"
	"testing"
)

type Todo struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

type store struct {
	mu    sync.Mutex
	todos []Todo
}

func (s *store) toggle(id int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for i := range s.todos {
		if s.todos[i].ID == id {
			s.todos[i].Done = !s.todos[i].Done
		}
	}
}

func (s *store) list() []Todo {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.todos
}

func TestListAfterToggle(t *testing.T) {
	s := &store{todos: []Todo{{1, "a", false}, {2, "b", false}}}
	s.toggle(1)
	if got := s.list(); !got[0].Done {
		t.Fatal("todo 1 should be done")
	}
}

func TestListWhileToggling(t *testing.T) {
	s := &store{todos: []Todo{{1, "a", false}, {2, "b", false}}}
	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		for range 1000 {
			json.NewEncoder(io.Discard).Encode(s.list())
		}
	}()
	go func() {
		defer wg.Done()
		for range 1000 {
			s.toggle(1)
		}
	}()
	wg.Wait()
}
